                rs = r;
            }
            ds.hardFail = rs.m.hard;
            var q = period - 1;
            ds.last = { roundScore: rs.score, res: ds.resHistory[q], low: ds.lowHistory[q], solv: ds.solvHistory[q],
                        pen: ds.penHistory[q], risk: ds.riskHistory[q], hard: rs.m.hard };
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            out.res = ds.last.res;
            out.low = ds.last.low;
            out.solv = ds.last.solv;
            out.pen = ds.last.pen;
            out.risk = ds.last.risk;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _annuity(bal, r, n) {
            if (n <= 0) { return bal; }
            if (r <= 0) { return bal / n; }
            return bal * r / (1.0 - Math.pow(1.0 + r, -n));
        }

        _scale(x) {
            var t = 0.0, lo = 0.0, i;
            for (i = 0; i < this.IRPF.length; i++) {
                var hi = this.IRPF[i][0];
                if (x > lo) { t += (Math.min(x, hi) - lo) * this.IRPF[i][1]; }
                lo = hi;
            }
            return t;
        }

        _irpf(x) {
            return Math.max(this._scale(Math.max(x, 0.0)) - this._scale(this.MINP), 0.0);
        }

        _event(dec, k) {
            var c = this.C;
            var a = {};
            var j, t;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var fo = this.FORMA[a.forma1];
            var iv = this.INV[a.inv1];
            var sl = (a.forma1 === 'sl' || a.forma1 === 'sl1');
            var shock = (k >= 3);
            var loan = iv[0];
            var nLeft = iv[2];
            var sgrShare = loan * iv[4];
            var capex0 = c.FIT + (iv[6] ? 0.0 : c.VAN);
            var cash = c.SAV - fo[0] + loan - sgrShare - capex0;
            var fixedNet = capex0;
            var wcPrev = 0.0;
            var owners = 0.0, pen = 0.0, lowMin = 1e18, expo = 0.0, fincost = 0.0;
            var negCarry = 0.0, posYears = 0, taxT = 0.0, odT = 0.0, dist = 0.0, prevEq = c.SAV;
            var last = null;
            for (t = 1; t <= 4; t++) {
                var pr = (t >= 2) ? this.PRECIO[a.precio2] : this.PRECIO.coste;
                var ivv = (t >= 2) ? this.IVA[a.iva2] : this.IVA.reservar;
                var im = (shock && t >= 3) ? this.IMPAGO[a.impago3] : this.NOIMP;
                var cr = (t === 4) ? this.CREC[a.crec4] : this.NOCREC;
                var so = (t === 4) ? this.SOCIOS[a.socios4] : [c.DRAW, 0.0, 0.0];
                var base = c.S[t - 1] * pr[0] * im[4];
                var sales = base * (1.0 + cr[0]);
                var gm = base * pr[1] + base * cr[0] * (pr[1] + cr[1] - cr[4]);
                var fixed = c.FIX[t - 1] + pr[2] + cr[2] + fo[1] + ivv[0] + fo[2] + (iv[6] ? this.RENT - this.RENT_SAVE : 0.0);
                var badd = sales * (im[2] + im[3]);
                var loss = 0.0, vatLoss = 0.0, vatRec = 0.0;
                if (shock && t === 3) {
                    loss = c.LOSS + im[0];
                    vatLoss = c.LOSS_VAT + im[0] * c.VAT;
                    vatRec = im[1] ? c.LOSS_VAT : 0.0;
                }
                var dep = ((t <= c.FIT_LIFE) ? c.FIT / c.FIT_LIFE : 0.0) + (iv[6] ? 0.0 : c.VAN / c.VAN_LIFE);
                var capex = cr[3];
                fixedNet += capex - dep;
                var intr = 0.0, princ = 0.0, gfee = 0.0, prepay = 0.0;
                if (t === 4 && a.crec4 === 'consolidar' && loan > 1e-6) {
                    prepay = Math.min(loan, Math.max(cash - this.CONS_KEEP, 0.0));
                    loan -= prepay;
                }
                if (loan > 1e-6) {
                    var r = iv[1] / 100.0;
                    gfee = loan * iv[3];
                    var pay = this._annuity(loan, r, nLeft);
                    intr = loan * r;
                    princ = pay - intr;
                    loan -= princ;
                    nLeft -= 1;
                }
                var q = this.QSHARE * gm + c.WH;
                var pY = 0.0, hole = 0.0;
                if (t >= 2) {
                    pY += q * this.LATE_ERR * ivv[3] + q * this.REJ * ivv[2] * 2.0;
                }
                if (shock && t === 3) {
                    var hs = q * (ivv[1] + ivv[2]);
                    var hc = this.HUECO[a.hueco3];
                    hole = vatLoss + hs;
                    pY += vatLoss * hc[0] + hs * hc[1];
                }
                pen += pY;
                var wc = sales * (c.WC_A - c.WC_L);
                var dwc = wc - wcPrev;
                wcPrev = wc;
                var pers = so[2];
                var draw = 2.0 * so[0];
                var biz = gm - fixed - badd - dep - intr - gfee - loss - pY;
                var divd = 0.0, compTax = 0.0, perT = 0.0, ptaxBiz = 0.0, net = 0.0, use = 0.0;
                if (sl) {
                    var b = biz - draw - pers;
                    if (b > 0) {
                        use = Math.min(negCarry, b); negCarry -= use; b -= use;
                        if (b > 0) {
                            posYears += 1;
                            compTax = (posYears <= 2) ? this.IS_NEW * b
                                : this.IS_MICRO[1] * Math.min(b, this.IS_MICRO[0]) + this.IS_MICRO[2] * Math.max(b - this.IS_MICRO[0], 0.0);
                        } else {
                            compTax = 0.0;
                        }
                    } else {
                        negCarry += -b; compTax = 0.0;
                    }
                    net = biz - draw - pers - compTax;
                    if (t === 4 && so[1] > 0) { divd = Math.max(prevEq - c.SAV, 0.0) * so[1]; }
                    perT = 2.0 * this._irpf(so[0]) + divd * this.DIVTAX;
                } else {
                    var y, yb;
                    if (a.forma1 === 'autonomo') {
                        y = biz - so[0] - pers;
                        yb = y;
                        if (yb > 0) { use = Math.min(negCarry, yb); negCarry -= use; yb -= use; } else { negCarry += -yb; yb = 0.0; }
                        perT = this._irpf(yb) + this._irpf(so[0]);
                    } else {
                        y = biz - pers;
                        yb = y;
                        if (yb > 0) { use = Math.min(negCarry, yb); negCarry -= use; yb -= use; } else { negCarry += -yb; yb = 0.0; }
                        perT = 2.0 * this._irpf(yb / 2.0);
                    }
                    net = biz - draw - pers;
                    if (t === 4 && so[1] > 0) { divd = Math.max(prevEq - c.SAV, 0.0) * so[1]; }
                    ptaxBiz = perT - ((a.forma1 === 'autonomo') ? this._irpf(so[0]) : 0.0);
                    net -= ptaxBiz;
                }
                var ownersNet = draw + pers + divd - perT;
                taxT += compTax + perT;
                var opcash = biz + dep - draw - pers - divd - (sl ? compTax : ptaxBiz) + vatRec;
                var flows = opcash - dwc - capex - princ - prepay;
                var peak = c.PEAK * sales;
                var low = cash + 0.5 * (opcash - dwc - princ) - capex - prepay - peak - ((shock && t === 3) ? vatLoss : 0.0)
                    - q * ivv[1];
                cash += flows;
                var od = Math.max(-low, 0.0) * c.OD;
                cash -= od; odT += od; fincost += intr + gfee + od;
                lowMin = Math.min(lowMin, low);
                owners += ownersNet;
                dist += divd;
                var assets = Math.max(cash, 0.0) + fixedNet + sales * c.WC_A + sgrShare;
                var liab = loan + sales * c.WC_L + Math.max(-cash, 0.0);
                var eq = assets - liab;
                prevEq = eq;
                var ex;
                if (fo[4] === 1) {
                    ex = liab;
                } else {
                    ex = fo[5] + ((iv[5] || a.forma1 === 'sl1') ? loan : 0.0);
                }
                expo = Math.max(expo, ex);
                last = { eq: eq, assets: assets, net: net, hole: hole };
            }
            var solv = (last.assets > 0) ? last.eq / last.assets : 0.0;
            var result = owners + last.eq - c.SAV;
            var hard = 0;
            for (j = 0; j < this.HARD.length; j++) {
                var gk = this.HARD[j][0];
                if (a[gk] === this.HARD[j][1] && k >= this.ROUND_OF[gk]) { hard += 1; }
            }
            return { k: k, a: a, res: result, low: lowMin, solv: solv, pen: pen, expo: expo, cash: cash, loan: loan,
                     eq: last.eq, owners: owners, fin: fincost, od: odT, tax: taxT, hard: hard, dist: dist };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.res - c.R_LO) / (c.R_HI - c.R_LO), 0, 1),
                    this._clamp((r.low - c.T_LO) / (c.T_HI - c.T_LO), 0, 1),
                    this._clamp((r.solv - c.S_LO) / (c.S_HI - c.S_LO), 0, 1),
                    this._clamp((c.P_LO - r.pen) / (c.P_LO - c.P_HI), 0, 1),
                    this._clamp((c.X_LO - r.expo) / (c.X_LO - c.X_HI), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_R, c.W_T, c.W_S, c.W_P, c.W_X];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = this._r2(n);
            var neg = v < 0;
            var cents = Math.round(Math.abs(v) * 100);
            var whole = Math.floor(cents / 100);
            var dec = cents - whole * 100;
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + (dec < 10 ? '0' : '') + String(dec);
            return (neg && cents > 0 ? '-' : '') + s;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var rH = ds.resHistory || [];
            var lH = ds.lowHistory || [];
            var sH = ds.solvHistory || [];
            var pH = ds.penHistory || [];
            var xH = ds.riskHistory || [];
            var n = rH.length;
            this._set('resDisplay', n ? this._fmtMoney(rH[n - 1]) : '-');
            this._set('lowDisplay', n ? this._fmtMoney(lH[n - 1]) : '-');
            this._set('solvDisplay', n ? this._fmtPct1(sH[n - 1]) : '-');
            this._set('penDisplay', n ? this._fmtMoney(pH[n - 1]) : '-');
            this._set('riskDisplay', n ? this._fmtMoney(xH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { forma1: 'fo', inv1: 'in', precio2: 'pr', iva2: 'iv', impago3: 'im', hueco3: 'hu', crec4: 'cr', socios4: 'so' };
            var opts = {
                forma1: ['autonomo', 'cb', 'sl', 'sl1'],
                inv1: ['ahorro', 'sgr', 'tarjeta', 'renting'],
                precio2: ['coste', 'valor', 'igualar', 'rebajas'],
                iva2: ['reservar', 'gestoria', 'circulante', 'aplazar'],
                impago3: ['rectificar', 'seguro', 'seguir', 'cortar'],
                hueco3: ['aplazar', 'tarde', 'sinpago', 'nodeclarar'],
                crec4: ['online', 'marketplace', 'nave', 'consolidar'],
                socios4: ['reservas', 'sueldos', 'reparto', 'personales']
            };
            var keys = {
                fb_fo_autonomo: 1, fb_fo_cb: 1, fb_fo_sl: 1, fb_fo_sl1: 1,
                fb_in_ahorro: 1, fb_in_sgr: 1, fb_in_tarjeta: 1, fb_in_renting: 1,
                fb_pr_coste: 1, fb_pr_valor: 1, fb_pr_igualar: 1, fb_pr_rebajas: 1,
                fb_iv_reservar: 1, fb_iv_gestoria: 1, fb_iv_circulante: 1, fb_iv_aplazar: 1,
                fb_im_rectificar: 1, fb_im_seguro: 1, fb_im_seguir: 1, fb_im_cortar: 1,
                fb_hu_aplazar: 1, fb_hu_tarde: 1, fb_hu_sinpago: 1, fb_hu_nodeclarar: 1,
                fb_cr_online: 1, fb_cr_marketplace: 1, fb_cr_nave: 1, fb_cr_consolidar: 1,
                fb_so_reservas: 1, fb_so_sueldos: 1, fb_so_reparto: 1, fb_so_personales: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                resChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Result for the partners', data: [], borderColor: '#2f6b4f', backgroundColor: 'rgba(47,107,79,0.12)', borderWidth: 2 },
                            { label: 'Lowest balance', data: [], borderColor: '#9a3b2f', backgroundColor: 'rgba(154,59,47,0.10)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#2f6b4f', backgroundColor: 'rgba(47,107,79,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var resHistory = ds.resHistory || [];
            var lowHistory = ds.lowHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = resHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                resChart: {
                    labels: labels,
                    datasets: [
                        { data: resHistory.slice(), label: this._t('chart_res') },
                        { data: lowHistory.slice(), label: this._t('chart_low') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var money = function(v) { return self._fmtMoney(v); };
            var pct = function(v) { return self._fmtPct1(v); };
            return [
                { key: 'results.res', label: 'Result for the partners', i18nKey: 'col_res', formatter: money },
                { key: 'results.low', label: 'Lowest cash balance', i18nKey: 'col_low', formatter: money },
                { key: 'results.solv', label: 'Solvency', i18nKey: 'col_solv', formatter: pct },
                { key: 'results.pen', label: 'Surcharges and penalties', i18nKey: 'col_pen', formatter: money },
                { key: 'results.risk', label: 'Personal assets at risk', i18nKey: 'col_risk', formatter: money },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var d = this._flat(state, mm);
            var m = this._event(d, mm);
            var kp = this._kpis(m);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                res: kp.res,
                low: kp.low,
                solv: kp.solv,
                pen: kp.pen,
                risk: kp.risk,
                cash: Math.round(m.cash),
                loan: Math.round(m.loan),
                eq: Math.round(m.eq),
                owners: Math.round(m.owners),
                dist: Math.round(m.dist),
                od: Math.round(m.od),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
